import static org.junit.Assert.*;
import static org.junit.Assert.assertNotNull;

/**
 * Unit tests for CoreOperationCompare constructor.
 */
public class CoreOperationCompare_CoreOperationCompare_TriageGen2Test {

    @Test
    public void testConstructor() {
        // Arrange
        Expression arg1 = new MockExpression();
        Expression arg2 = new MockExpression();

        // Act
        CoreOperationCompare operation = new CoreOperationCompare(arg1, arg2);

        // Assert
        assertNotNull("The created operation should not be null", operation);
    }

    @Test
    public void testConstructorWithNulls() {
        // Arrange & Act
        // Testing with nulls to ensure the constructor handles them according to the super call
        CoreOperationCompare operation = new CoreOperationCompare(null, null);

        // Assert
        assertNotNull("The created operation should not be null even with null arguments", operation);
    }

    /**
     * Mock Expression class to satisfy the Expression dependency.
     */
    private static class MockExpression implements Expression {
        @Override
        public Object evaluate(org.apache.commons.jxpath.EvalContext context) {
            return null;
        }

        @Override
        public org.apache.commons.jxpath.EvalContext getContext() {
            return null;
        }
    }
}
